import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-block-list',
  templateUrl: './block-list.page.html',
  styleUrls: ['./block-list.page.scss'],
})
export class BlockListPage implements OnInit {
  teacher_id: any;
  blocklistActive: boolean;
  blocklist: any;
  blockLength: any;
  blockListCopy: any;
  distId: any;
 
  constructor(public router:Router,private emisService: EmisService,private userService: UserService,private alertService:AlertService,private userSessionService: UserSessionService) { }

  ngOnInit() {
  }
  ionViewDidEnter() {
    this.teacher_id = this.userSessionService.teacher_id();
    this.distId = this.userSessionService.district_id();
    this.getUserDetails();
  }
  backBtn(){
    this.router.navigate(["/tabs/home"])
  }
  getUserDetails() {  
    this.userService.getOoscUserDetails(this.teacher_id).subscribe(res => { 
      console.log("result",res);
      if (res.dataStatus == true ) {
        var uerDetails = res.result;
        if (uerDetails.length > 0) {
            this.getBlockList(this.distId);
        } else {
          this.blocklistActive = false;
        }
      } else {
        this.alertService.error("Something went wrong");
      }
    });
}

  getBlockList(distId) {
    this.emisService.getBlockList(distId).subscribe(res => {
      console.log(res,'test')
      if (res.dataStatus == true ) {
        var block = res.result;
        if (block.length > 0) {
          this.blockLength = block.length;
          this.blocklistActive = true;
          this.blocklist = block.map(l => { return { label: l.block_name, value: l.id }; });
          this.blocklist.sort((a, b) => {
            if (a.label < b.label)
              return -1;
            if (a.label > b.label)
              return 1;
            return 0;
          });
          this.blockListCopy = this.blocklist;
        } else {
          this.blocklistActive = false;
        }
      } else {
      this.blocklistActive = false;
    }
    });
  }
getarpenrollment(item){
  this.router.navigate(["/tabs/art-culture"] ,{ queryParams: {blockId: item.value} });
}
}
